  fprintf(fid, "`define P_COMM_PHA \t%d\n",defines.p_comm_phase);
  fprintf(fid, "`define P_OUP_W     \t(`P_INP_DATA_W+`P_COEFF_W+(`DIV(`P_COEFF_L,`P_INTERPOLATION)))\n");
